Arguments:
$rows = @(Get-Content -Raw artifacts/ecs-relations/measurements/optimized-20/summary.json | ConvertFrom-Json | Where-Object Required)
foreach ($group in ($rows | Group-Object { ($_.CaseId -split '-')[0] })) { '{0}: {1}/{2}' -f $group.Name,@($group.Group | Where-Object Status -eq 'pass').Count,$group.Count }
foreach ($row in $rows) { '{0} {1:G17} {2:G17} {3}' -f $row.CaseId,$row.MedianRatio,$row.P95Ratio,$row.Status }
